# 風格化聊天
這是一款簡單的模組，讓伺服器主可以自訂聊天室的外觀！

它新增了對Minecraft支援的[現代聊天格式](https://placeholders.pb4.eu/user/text-format/)的支援，但許多聊天模組/插件都忽略了這一點。

它還相容於任何使用[Placeholder API](https://placeholders.pb4.eu/user/general/)的模組。

它還支援透過權限系統（支援LuckPerms和PlayerRoles）為每位玩家設定不同的風格。

*此模組僅適用於Fabric Mod Loader及其相容版本！*

如果有任何問題，可以在我的[Discord](https://pb4.eu/discord)上提問。

[也可以看看我的其他模組和專案，說不定你會覺得它們很有用！](https://pb4.eu)

![範例圖片](https://i.imgur.com/HPSMaS8.png)
![範例圖片2](https://i.imgur.com/mSWzIV4.png)


## 指令（及權限）：
- `/styledchat` - 主要指令（`styledchat.main`，預設可用）
- `/styledchat reload` - 重新載入設定和風格（需要`styledchat.reload`權限）
- `/styledchat set <玩家> <類型> <值>` - 變更<玩家>的<類型>風格為<值>（需要`styledchat.set`權限）
- `/styledchat get <玩家> <類型>` - 查詢<玩家>的<類型>風格（需要`styledchat.get`權限）
- `/styledchat clear <玩家> <類型>` - 清除<玩家>的<類型>風格（需要`styledchat.clear`權限）

## 設定：
你可以在`./config/styled-chat.json`找到設定檔。
[格式化使用簡化文字格式](https://placeholders.pb4.eu/user/text-format/)。
它支援使用[Placeholder API](https://placeholders.pb4.eu/user/general/)的佔位符。
此外，每種訊息類型都有一些自己的區域變數。

```json5
{
  "CONFIG_VERSION_DONT_TOUCH_THIS": 3,
  "_comment": "在變更任何設定前，請參閱https://github.com/Patbox/StyledChat#configuration",
  "text_formatting": {
    // 啟用聊天中的連結解析
    "parse_links": true,
    // 啟用Markdown
    "markdown": true,
    // 啟用聊天中的舊版(&x)代碼支援（僅限玩家輸入時）
    "legacy_formatting": false,
    // 啟用其他模組的格式化（如果模組實作不正確，可能會破壞StyledChat的格式化）
    "formatting_from_other_mods": false
  },
  "chat_preview": {
    // 在聊天預覽中發送完整訊息（包含所有格式化）
    "send_full_message": false,
    // 需要聊天預覽才能套用格式化，否則停用
    "require_for_formatting": false
  },
  "auto_completion": {
    // 啟用標籤的自動完成（例如<red>、<rainbow>）
    "tags": false,
    // 啟用標籤別名的自動完成（例如<c>、<rb>）
    "tag_aliases": false,
    // 啟用表情符號的自動完成（例如:pos:、:item:）
    "emoticons": false
  },
  // 預設風格設定
  "default": {
    // 顯示名稱（區域變數：${default}、${name}）
    "display_name": "${default}",
    // 訊息風格
    "message_formats": {
      // 聊天訊息風格（區域變數：${player}、${message}）
      "chat": "<${player}> ${message}",
      // 加入訊息（區域變數：${player}）
      "joined_the_game": "<yellow><lang:multiplayer.player.joined:'${player}'></yellow>",
      // 名稱變更後的加入訊息（區域變數：${player}、${old_name}）
      "joined_after_name_change": "<yellow><lang:multiplayer.player.joined.renamed:'${player}':'${old_name}'></yellow>",
      // 首次加入的玩家訊息（區域變數：${player}）
      "joined_for_first_time": "<yellow><lang:multiplayer.player.joined:'${player}'></yellow>",
      // 玩家離開伺服器（區域變數：${player}）
      "left_game": "<yellow><lang:multiplayer.player.left:'${player}'></yellow>",
      // 玩家死亡訊息（區域變數：${player}、${default_message}）
      "base_death": "${default_message}",
      // 完成進度任務（區域變數：${player}、${advancement}）
      "advancement_task": "<lang:chat.type.advancement.task:'${player}':'${advancement}'>",
      // 完成進度挑戰（區域變數：${player}、${advancement}）
      "advancement_challenge": "<lang:chat.type.advancement.challenge:'${player}':'${advancement}'>",
      // 完成進度目標（區域變數：${player}、${advancement}） 
      "advancement_goal": "<lang:chat.type.advancement.goal:'${player}':'${advancement}'>",
      // 隊伍訊息，對發送者可見（區域變數：${team}、${displayName}、${message}）
      "sent_team_chat": "<lang:'chat.type.team.sent':'<hover\\:\\'<lang\\:chat.type.team.hover>\\'><suggest_command\\:\\'/teammsg \\'>${team}':'${displayName}':'${message}'>",
      // 隊伍訊息，對其他隊員可見（區域變數：${team}、${displayName}、${message}）
      "received_team_chat": "<lang:'chat.type.team.text':'<hover\\:\\'<lang\\:chat.type.team.hover>\\'><suggest_command\\:\\'/teammsg \\'>${team}':'${displayName}':'${message}'>",
      // 私人訊息，對發送者可見（區域變數：${receiver}、${sender}、${message}）
      "sent_private_message": "<gray><italic><lang:commands.message.display.outgoing:'${receiver}':'${message}'>",
      // 私人訊息，對接收者可見（區域變數：${receiver}、${sender}、${message}）
      "received_private_message": "<gray><italic><lang:commands.message.display.incoming:'${sender}':'${message}'>",
      // /say指令輸出（區域變數：${player}、${message}）
      "say_command": "[${player}] ${message}",
      // /me指令輸出（區域變數：${player}、${message}）
      "me_command": "<lang:'chat.type.emote':'${player}':'${message}'>",
      // 玩家寵物死亡時發送的死亡訊息（區域變數：${default_message}、${pet}）
      "pet_death": "${default_message}"
    },
    // 連結風格（區域變數：${link}、${url}）
    "link_style": "<underline><c:#7878ff>${link}",
    // 劇透風格（區域變數：${spoiler}）
    "spoiler_style": "<gray>${spoiler}",
    // 劇透風格中使用的劇透符號
    "spoiler_symbol": "▌",
    // 玩家可使用的格式化
    "formatting": {
      // "格式化標籤": true/false
      "dark_red": true,
      "green": true,
      "underline": true,
      "dark_green": true,
      "black": true,
      "yellow": true,
      "bold": true,
      "italic": true,
      "dark_blue": true,
      "dark_purple": true,
      "gold": true,
      "red": true,
      "aqua": true,
      "gray": true,
      "light_purple": true,
      "blue": true,
      "white": true,
      "dark_aqua": true,
      "dark_gray": true,
      "spoiler": true,
      "strikethrough": true
    },
    // 玩家可使用的表情符號清單（聊天中的:名稱:）。支援佔位符
    "emoticons": {
      // "名稱": "值"
      "potion": "🧪",
      "item": "[%player:equipment_slot mainhand%]",
      "trident": "🔱",
      "rod": "🎣",
      "shrug": "¯\\_(ツ)_/¯",
      "bow": "🏹",
      "bell": "🔔",
      "heart": "❤",
      "bucket": "🪣",
      "sword": "🗡",
      "shears": "✂",
      "pos": "%player:pos_x% %player:pos_y% %player:pos_z%",
      "fire": "🔥",
      "table": "(╯°□°）╯︵ ┻━┻",
      // 從2.2.1+1.20.1版本開始，你也可以使用以下語法從檔案導入。
      "$emojibase:builtin:joypixels": "${emoji}",
      // 值與其他相同，只是${emoji}會被替換為讀取的表情符號（所以你可以應用字體等）
      // 格式如下：$TYPE:SOURCE:PATH
      // TYPE可以是"emojibase"（Emojibase.dev簡寫）、"cldr"（Unicode cldr-json註釋）
      //      或"default"（與此檔案相同的風格，不包括導入）
      // SOURCE指向儲存類型，PATH指向檔案
      //     "builtin"從模組捆綁的json載入（"joypixels"或"emojibase"）
      //     "from_file"從設定目錄相對路徑載入檔案（例如"emoji.json"指向"[SERVER]/config/emoji.json）

    }
  },
  // 帶有某些需求的風格清單，從上到下套用
  "styles": [
    {
      // 套用風格給玩家的需求
      "require": {
        "type": "...",
        // 關於這些的資訊請參閱：https://github.com/Patbox/PredicateAPI/blob/master/BUILTIN.md
      },
      /* 其餘與"default"欄位相同，除了所有欄位都是完全可選的 */
    }
  ]
}
```

## 聊天中的格式化
如果玩家擁有必要的權限（`styledchat.format.[標籤名稱]`，其中`[標籤名稱]`是文字解析器標籤），則他們可以在聊天中使用簡化文字標籤。
此外，你可以在設定中啟用Markdown和舊版(&X)格式化


## 設定範例
```json 
{
  "CONFIG_VERSION_DONT_TOUCH_THIS": 3,
  "_comment": "在變更任何設定前，請參閱https://github.com/Patbox/StyledChat#configuration",
  "text_formatting": {
    "legacy_formatting": true,
    "parse_links": true,
    "markdown": true,
    "formatting_from_other_mods": true
  },
  "chat_preview": {
    "send_full_message": false,
    "require_for_formatting": false
  },
  "auto_completion": {
    "tags": false,
    "tag_aliases": false,
    "emoticons": true
  },
  "default": {
    "display_name": "${vanillaDisplayName}",
    "message_formats": {
      "chat": "${player} <dark_gray>»</dark_gray> ${message}",
      "joined_the_game": "<gray>✚</gray> <color:#85ff8f><lang:multiplayer.player.joined:'${player}'>",
      "joined_after_name_change": "<gray>✚</gray> <color:#85ff8f><lang:multiplayer.player.joined.renamed:'${player}':'${old_name}'>",
      "joined_for_first_time": "<yellow><lang:multiplayer.player.joined:'${player}'></yellow>",
      "left_game": "<gray>☁</gray> <color:#ff8585><lang:multiplayer.player.left:'${player}'>",
      "base_death": "<gray>☠</gray> <color:#d1d1d1>${default_message}",
      "advancement_task": "<lang:chat.type.advancement.task:'${player}':'${advancement}'>",
      "advancement_challenge": "<lang:chat.type.advancement.challenge:'${player}':'${advancement}'>",
      "advancement_goal": "<lang:chat.type.advancement.goal:'${player}':'${advancement}'>",
      "sent_team_chat": "<lang:'chat.type.team.sent':'<hover\\:\\'<lang\\:chat.type.team.hover>\\'><suggest_command\\:\\'/teammsg \\'>${team}':'${displayName}':'${message}'>",
      "received_team_chat": "<lang:'chat.type.team.text':'<hover\\:\\'<lang\\:chat.type.team.hover>\\'><suggest_command\\:\\'/teammsg \\'>${team}':'${displayName}':'${message}'>",
      "sent_private_message": "<gray>[<green>PM</green> → ${receiver}] <dark_gray>»<reset> ${message}",
      "received_private_message": "<gray>[<green>PM</green> ← ${sender}] <dark_gray>»<reset> ${message}",
      "say_command": "<red>[${player}] ${message}",
      "me_command": "<green>* ${player} ${message}",
      "pet_death": "Oh no! ${default_message}"
    },
    "link_style": "<underline><blue>${link}",
    "spoiler_style": "<dark_gray>${spoiler}",
    "spoiler_symbol": "▌",
    "formatting": {
      "dark_red": true,
      "underline": true,
      "yellow": true,
      "italic": true,
      "dark_blue": true,
      "dark_purple": true,
      "gold": true,
      "red": true,
      "aqua": true,
      "gray": true,
      "light_purple": true,
      "white": true,
      "pos": true,
      "dark_gray": true,
      "spoiler": true,
      "strikethrough": true,
      "st": true,
      "b": true,
      "item": true,
      "green": true,
      "dark_green": true,
      "black": true,
      "i": true,
      "bold": true,
      "blue": true,
      "dark_aqua": true
    },
    "emoticons": {
      "potion": "🧪",
      "trident": "🔱",
      "rod": "🎣",
      "shrug": "¯\\_(ツ)_/¯",
      "bow": "🏹",
      "bell": "<yellow>🔔",
      "heart": "<red>❤",
      "bucket": "🪣",
      "sword": "🗡",
      "shears": "✂",
      "fire": "🔥",
      "table": "<rb>(╯°□°）╯︵ ┻━┻"
    }
  },
  "styles": [
    {
      "require": {
        "type": "permission",
        "permission": "group.admin",
        "operator": 4
      },
      "display_name": "<dark_gray>[<red>管理員</red>]</dark_gray> <c:#ffe8a3>${vanillaDisplayName}</c>",
      "message_formats": {
        "chat": "${player} <dark_gray>»</dark_gray> <orange>${message}",
        "base_death": ""
      },
      "formatting": {},
      "emoticons": {}
    },
    {
      "require": {
        "type": "permission",
        "permission": "group.default"
      },
      "display_name": "<dark_gray>[<aqua>玩家</aqua>]</dark_gray> <dark_aqua>${vanillaDisplayName}</dark_aqua>",
      "message_formats": {},
      "formatting": {},
      "emoticons": {}
    },
    {
      "require": {
        "type": "permission",
        "permission": "group.vip",
        "operator": 3
      },
      "message_formats": {},
      "formatting": {},
      "emoticons": {
        "potato": "<rb>馬鈴薯"
      }
    }
  ]
}
